    resourceKey: string;           // taskAssignmentBoard
    pathParams: Record<string, string>; // { taskId: "{taskId}", id: "{id}" }
  };
}
```

`FormFieldSchema` 增加可选字段：`arrayTable?: ArrayTableMeta`、`link?: LinkFieldMeta`。

### 3.2 `ArrayTableFieldControl` 行为分支

| `arrayTable.mode` | 行为 |
|-------------------|------|
| `editable`（默认） | **保持现状** |
