      if (event.action === "openDetail" && event.row) {
        setDetailState({ open: true, itemId: Number(event.row.id) });
      }
    },
  };

  return (
    <>
      <LHResourceForm
        resource={batchAssignWorkflowResource}
        mode="create"
        values={values}
        formId="batch-assign-form"
        onChange={(key, value) => setValues((v) => setValueAtPath(v, key, value))}
