      <LHDetailDrawer
        resource={taskAssignmentBoardResource}
        recordId={detailState.itemId}
        pathParams={{ taskId }}
        open={detailState.open}
        onClose={() => setDetailState({ open: false })}
      />
    </>
  );
}
