```ts
interface LHDynamicTableProps {
  columns: TableColumnSchema[];
  records: ResourceRecord[];
  rowKey?: string;                    // default "id"
  dictOptions?: Record<string, OptionItem[]>;

  selectable?: boolean;
  selectedRowKeys?: Array<string | number>;
