  /** 动作码，由宿主解释（见下） */
  action: "detail" | "edit" | "workflow" | string;
  /** action=detail：可指定资源；默认走宿主 openDetail */
  resourceKey?: string;
  /** action=workflow：workflow.rendererCode */
  workflowCode?: string;
  /** action=navigate */
  href?: string;
  openInNewTab?: boolean;
  /** 路径参数模板：{ taskId: "{taskId}", id: "{id}" } */
  pathParams?: Record<string, string>;
}

export interface TableColumnSchema {
  // ...existing
  type?: TableColumnType;
  link?: TableColumnLinkMeta;
}
```

**侧栏「题目」列示例**（分配管理 `task-assignment-board.ts`）：

```ts
{
  key: "sourceItemKey",
  title: "题目",
  type: "link",
  link: {
    labelField: "sourceItemKey",
    action: "detail",
    resourceKey: "taskAssignmentBoard",
    pathParams: { taskId: "{taskId}", id: "{id}" },
  },
},
```

**`LHDynamicTable` 渲染 `link` 列**

- 单元格渲染为 `<button type="button" className="lh-table-link">` + formatter 文案。
- 点击 `stopPropagation`，触发 `onCellAction({ action, column, record })`。
- 点击区域排除 checkbox / 操作列（与现有 picker 行点击逻辑一致）。

