## 五、`LHResourceForm` 新字段：`dynamicTable`（不是 `array`）

### 5.1 `FormFieldSchema` 扩展

```ts
export interface FormDynamicTableMeta {
  /** 列定义，与 resource.table.columns 同构 */
  columns: TableColumnSchema[];
  rowKey?: string;
  selectable?: boolean;
  /** 选中行 id 列表写入的表单 path，如 selectedItemIds */
  selectionPath?: string;
  pagination?: boolean | "client";    // client=前端切页，false=不分页
  pageSize?: number;
  maxHeight?: number;
  hideActionsColumn?: boolean;
  empty?: { title?: string; description?: string };
  /** 行是否可选（批量指派：assignable === true） */
