}

export interface FormFieldSchema {
  // ...
  component: string;  // 新增 "dynamicTable"
  dynamicTable?: FormDynamicTableMeta;
}
```

### 5.2 表单值绑定

```ts
{
  labelerId: 1001,
  deadlineAt: "2026-06-01T18:00",
  candidates: BoardRow[],      // dynamicTable 的 dataPath = "candidates"
  selectedItemIds: number[],   // selectionPath = "selectedItemIds"
