## 2. `LHResourceForm` 怎么接（几乎不动壳子）

逻辑放在 `use-resource-form-engine.core.tsx`：

```tsx
if (field.component === "dynamicTable" && field.dynamicTable) {
  const rows = getValueAtPath(values, path) ?? [];
  const selectionPath = field.dynamicTable.selectionPath ?? "selectedItemIds";

  // 用字段配置拼一个「最小 ResourceMeta」，喂给 LHDataTable
  const tableResource = buildTableResourceFromField(field, resource);

  return (
    <SharedField className="lh-form-field--full" ...>
      <LHDataTable
        resource={tableResource}
        records={rows}
        total={rows.length}
        selectedRowKeys={getValueAtPath(values, selectionPath) ?? []}
        onSelectionChange={(keys) => updateFieldValue(selectionPath, keys)}
        onDetail={(record) =>
          formContext?.onTableAction?.({ action: "detail", record, field })
        }
        onAction={(action, record) =>
          formContext?.onTableAction?.({ action: action.key, record, field })
