      hiddenInList: true,
      permission: ["system:admin", "business:assignment:update"],
      confirm: {
        title: "确认取消选中的 {count} 项分配？",
        ...
      },
    },
```

`resolveResourceBulkActions` 会对每个 ref 调用 `mergeBulkAction(ref, resource.actions)`：用 `actions` 里 `key === "batchCancel"` 的项做底，再用 `table.bulkActions` 覆盖 `label` / `kind` 等。  
**若 `actions` 里没有同名 key，合并结果为 `null`，批量按钮不会出现。**

## 2. UI：何时出现、点谁

```475:478:frontend/src/low-code/components/resource-page/LHResourcePage.tsx
  const bulkActions = useMemo(
    () => resolveResourceBulkActions(resource),
    [resource],
  );
```

勾选行后（`selectable: true` + `selectedRowKeys`），底部渲染 `LHTableBulkActionBar`，点击「批量取消分配」→ `handleBulkAction(action)`。

## 3. `handleBulkAction` 里 `kind: "request"` 走哪条分支

`batchCancel` 不是 `assignment` / `workflow` / `drawer`，会落到**默认批量分支**：

```564:577:frontend/src/low-code/components/resource-page/LHResourcePage.tsx
    await confirmAction.openOrRunAction(
      action,
      async () => {
        try {
          await mutations.runBulkAction({ resource, action, ids });
          state.setSelectedRowKeys([]);
          await refresh();
        } catch (error) {
          ...
        }
      },
      { count },
    );
```

- `ids` = 当前勾选行的 `id`（`idKey: "id"`，即分配主键）
- 有 `confirm` 会先弹确认框，再执行上面回调

`kind: "request"` 在这里**不表示**走 `runResourceAction` 的单条 POST，只表示「普通批量请求」，和 drawer/workflow 等区分开。

## 4. `runBulkAction` → 插件注册表（不经过 `request.ts` 特例）

```144:157:frontend/src/low-code/hooks/use-resource-mutations.ts
  const runBulkResourceActionMutation = useCallback(
    async (request: EngineBulkActionRequest) => {
      ...
      const registeredHandler = resolveBulkResourceAction(
        request.resource.resource,
        request.action.key,
      );
      if (registeredHandler) {
        const scope = resolveBulkActionScope(request, listQuery);
        await registeredHandler(scope ? { ...request, scope } : request);
        await invalidateResourceList();
        return;
      }
      // 否则走 Refine custom → dataProvider → runBulkResourceAction（需 bulkApi / engine）
```

对 `assignments` + `batchCancel`，查找键为 **`assignments:batchCancel`**，在 `main.tsx` 安装的插件里注册：

```20:23:frontend/src/features/business/plugins/business-low-code-plugin.ts
    api.bulkActions.register("taskAssignmentBoard", "batchCancel", runTaskAssignmentBoardBatchCancel);
    api.bulkActions.register("assignments", "batchCancel", runAssignmentsBatchCancel);
```

## 5. 最终 HTTP（assignments 列表页）

```62:64:frontend/src/features/business/assignments/assignment-actions.ts
export async function runAssignmentsBatchCancel(requestInput: EngineBulkActionRequest): Promise<void> {
  await cancelAssignmentsByIds(requestInput.ids);
